CRO_tr=CRO_rd;
CRO_tr.y=year(CRO_tr.Time);
% begin at the beginning of a year:2004
%end year: 2013
P=timerange('2004-01-01','2013-01-01');
CRO_tr=CRO_tr(P,:);

names=fieldnames(CRO_tr);
c= startsWith(names,["T1";"T0";"T_";"P_";"P1_";"P0_"]) | endsWith(names,'T');
N=names(c);
for i=1:length(N)
    CRO_tr.(N{i})=[];
end
